import * as XLSX from 'xlsx';
import type { PlanScheduleType, PlanVoucherImportRowDto } from '../../../services/fpc/types';

/** Normalize Excel header → canonical field key. */
function mapHeader(raw: string): string | null {
  const h = (raw || '')
    .trim()
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/\s+/g, '')
    .replace(/[_-]/g, '');

  const aliases: Record<string, string> = {
    madonvi: 'companyCode',
    companycode: 'companyCode',
    branchcode: 'companyCode',
    companyid: 'companyCode',
    madvcs: 'companyCode',
    donvicoso: 'companyCode',
    chinhanh: 'companyCode',
    machiphi: 'costCode',
    costcode: 'costCode',
    chiphi: 'costCode',
    doituong: 'costCode',
    nam: 'year',
    year: 'year',
    planyear: 'year',
    thang: 'month',
    month: 'month',
    planmonth: 'month',
    sotienkehoach: 'plannedAmount',
    kehoach: 'plannedAmount',
    kehoachchi: 'plannedAmount',
    plannedamount: 'plannedAmount',
    amount: 'plannedAmount',
    phaichi: 'mustPay',
    mustpay: 'mustPay',
    diengiai: 'note',
    note: 'note',
    ghichu: 'note',
    description: 'note',
    lichrieng: 'lichRiengRaw',
    usecustomschedule: 'lichRiengRaw',
    loailich: 'loaiLichRaw',
    schedulekind: 'loaiLichRaw',
    fixed: 'loaiLichRaw',
    recurring: 'loaiLichRaw',
    tansuat: 'tanSuatRaw',
    planscheduletype: 'tanSuatRaw',
    frequency: 'tanSuatRaw',
    tansuatlapp: 'tanSuatRaw',
    giatrilich: 'giaTriLichRaw',
    schedulevalue: 'giaTriLichRaw',
    giatri: 'giaTriLichRaw',
    ngaytu: 'ngayTuRaw',
    tu: 'ngayTuRaw',
    tungay: 'ngayTuRaw',
    effectivefrom: 'ngayTuRaw',
    ngayden: 'ngayDenRaw',
    den: 'ngayDenRaw',
    denngay: 'ngayDenRaw',
    effectiveto: 'ngayDenRaw',
    ngaycodinh: 'ngayCoDinhRaw',
    fixeddate: 'ngayCoDinhRaw',
    loainhom: 'entityMode',
    loaihieu: 'entityMode',
    loaiphieu: 'entityMode',
    entitymode: 'entityMode',
    mode: 'entityMode',
  };
  return aliases[h] ?? null;
}

function cellStr(v: unknown): string {
  if (v == null) return '';
  if (typeof v === 'string') return v.trim();
  if (typeof v === 'number' && Number.isFinite(v)) {
    // Excel date serial → leave as number string for BE ParseDate
    return String(v);
  }
  if (v instanceof Date && !Number.isNaN(v.getTime())) {
    const y = v.getFullYear();
    const m = String(v.getMonth() + 1).padStart(2, '0');
    const d = String(v.getDate()).padStart(2, '0');
    return `${y}-${m}-${d}`;
  }
  return String(v).trim();
}

function cellNum(v: unknown): number {
  if (v == null || v === '') return 0;
  if (typeof v === 'number' && Number.isFinite(v)) return v;
  const s = String(v).replace(/\s/g, '').replace(/,/g, '');
  const n = Number(s);
  return Number.isFinite(n) ? n : 0;
}

function cellInt(v: unknown): number {
  return Math.trunc(cellNum(v));
}

function stripCodeName(value: string): string {
  // SSOT dropdown: "CODE - Name" (space-hyphen-space). Codes may contain hyphens (FM-DC).
  const sep = value.indexOf(' - ');
  if (sep > 0) return value.slice(0, sep).trim();
  const m = value.match(/^\s*(.+?)\s+-\s+/);
  if (m) return m[1].trim();
  return value.trim();
}

function isYes(s: string): boolean {
  const raw = s.trim();
  if (!raw) return false;
  if (isNo(raw)) return false;
  const code = stripCodeName(raw).toLowerCase();
  if (code === 'có' || code === 'co' || code === 'yes' || code === 'y' || code === 'true' || code === '1') return true;
  const t = raw.toLowerCase();
  return t.startsWith('y -') || t.startsWith('y-') || t === 'có' || t === 'co';
}

function isNo(s: string): boolean {
  const raw = s.trim();
  if (!raw) return false;
  const code = stripCodeName(raw).toLowerCase();
  if (code === 'không' || code === 'khong' || code === 'no' || code === 'n' || code === 'false' || code === '0') return true;
  const t = raw.toLowerCase();
  return t.startsWith('n -') || t.startsWith('n-') || t.includes('không') || t.includes('khong');
}

/**
 * Parse sheet `KeHoach` (or first sheet) → import rows.
 * Columns: MaDonVi (MÃ - Tên), MaChiPhi, Nam, Thang, money, schedule fields.
 */
export function parsePlanVoucherImportFile(file: ArrayBuffer): PlanVoucherImportRowDto[] {
  const wb = XLSX.read(file, { type: 'array', cellDates: true });
  const sheetName =
    wb.SheetNames.find(n => n.localeCompare('KeHoach', undefined, { sensitivity: 'accent' }) === 0)
    ?? wb.SheetNames.find(n => /ke\s*hoach|import|data/i.test(n))
    ?? wb.SheetNames[0];
  if (!sheetName) return [];

  const sheet = wb.Sheets[sheetName];
  const matrix = XLSX.utils.sheet_to_json<(string | number | null | undefined)[]>(sheet, {
    header: 1,
    defval: '',
    raw: true,
  }) as unknown[][];

  if (!matrix.length) return [];

  const headerRow = matrix[0] as unknown[];
  const colMap = new Map<number, string>();
  headerRow.forEach((cell, i) => {
    const key = mapHeader(cellStr(cell));
    if (key) colMap.set(i, key);
  });

  if (colMap.size === 0) {
    throw new Error(
      'Không nhận diện được header. Tải file mẫu: MaDonVi, MaChiPhi, Nam, Thang, SoTienKeHoach, LichRieng, LoaiLich, …',
    );
  }

  const rows: PlanVoucherImportRowDto[] = [];
  for (let r = 1; r < matrix.length; r++) {
    const line = matrix[r] as unknown[];
    if (!line || line.every(c => cellStr(c) === '')) continue;

    const obj: Record<string, unknown> = {};
    colMap.forEach((key, i) => {
      obj[key] = line[i];
    });

    const companyCode = cellStr(obj.companyCode);
    const costCode = cellStr(obj.costCode);
    const year = cellInt(obj.year);
    const month = cellInt(obj.month);
    const plannedAmount = cellNum(obj.plannedAmount);
    const mustPay = cellNum(obj.mustPay);
    const note = cellStr(obj.note) || undefined;

    const lichRiengRaw = cellStr(obj.lichRiengRaw) || undefined;
    const loaiLichRaw = cellStr(obj.loaiLichRaw) || undefined;
    const tanSuatRaw = cellStr(obj.tanSuatRaw) || undefined;
    const giaTriLichRaw = cellStr(obj.giaTriLichRaw) || undefined;
    const ngayTuRaw = cellStr(obj.ngayTuRaw) || undefined;
    const ngayDenRaw = cellStr(obj.ngayDenRaw) || undefined;
    const ngayCoDinhRaw = cellStr(obj.ngayCoDinhRaw) || undefined;

    if (!companyCode && !costCode && plannedAmount === 0 && mustPay === 0) continue;

    const useCustom =
      (lichRiengRaw ? isYes(lichRiengRaw) : false)
      || (!!loaiLichRaw && !isNo(lichRiengRaw || ''))
      || !!ngayCoDinhRaw
      || !!tanSuatRaw;

    rows.push({
      rowIndex: r + 1,
      companyCode: (stripCodeName(companyCode) || companyCode).toUpperCase(),
      costCode: stripCodeName(costCode) || costCode,
      year,
      month,
      plannedAmount,
      mustPay,
      note,
      entityMode: cellStr(obj.entityMode)
        ? stripCodeName(cellStr(obj.entityMode)).toLowerCase().replace(/_/g, '-')
        : undefined,
      useCustomSchedule: isNo(lichRiengRaw || '') ? false : useCustom,
      lichRiengRaw,
      loaiLichRaw,
      tanSuatRaw,
      giaTriLichRaw,
      ngayTuRaw,
      ngayDenRaw,
      ngayCoDinhRaw,
      // Structured hints — BE re-normalizes fully from *Raw
      planScheduleType: tanSuatRaw
        ? (stripCodeName(tanSuatRaw) as PlanScheduleType)
        : loaiLichRaw && /fixed|cố định|co dinh/i.test(loaiLichRaw)
          ? 'Once'
          : loaiLichRaw && /recurring|định kỳ|dinh ky/i.test(loaiLichRaw)
            ? 'ByDay'
            : undefined,
      scheduleValue: giaTriLichRaw || undefined,
    });
  }

  return rows;
}
