import React, { useCallback, useRef, useState } from 'react';
import {
  Button,
  dispatchAppToast,
} from '@linm-soft-org/linm-web-common-components';
import { Modal } from '@/components/common';
import { useAppDispatch } from '../../../store/hooks';
import { fpcService } from '../../../services/fpc/service';
import type {
  PlanVoucherImportResultDto,
  PlanVoucherImportRowDto,
} from '../../../services/fpc/types';
import { parsePlanVoucherImportFile } from './parsePlanVoucherImportFile';
import styles from './PlanVoucherImportModal.module.css';

const TEST_ID = 'plan-voucher-import';

export type PlanVoucherImportModalProps = {
  open: boolean;
  onClose: () => void;
  onImported: () => void;
};

const PlanVoucherImportModal: React.FC<PlanVoucherImportModalProps> = ({
  open,
  onClose,
  onImported,
}) => {
  const dispatch = useAppDispatch();
  const fileRef = useRef<HTMLInputElement>(null);
  const [fileName, setFileName] = useState('');
  const [rows, setRows] = useState<PlanVoucherImportRowDto[]>([]);
  const [parseError, setParseError] = useState<string | null>(null);
  const [result, setResult] = useState<PlanVoucherImportResultDto | null>(null);
  const [downloading, setDownloading] = useState(false);
  const [importing, setImporting] = useState(false);

  const resetState = useCallback(() => {
    setFileName('');
    setRows([]);
    setParseError(null);
    setResult(null);
    if (fileRef.current) fileRef.current.value = '';
  }, []);

  const handleClose = () => {
    if (importing) return;
    resetState();
    onClose();
  };

  const handleDownloadTemplate = async () => {
    setDownloading(true);
    try {
      await fpcService.downloadPlanVoucherImportTemplate();
      dispatchAppToast(dispatch, {
        message: 'Đã tải mẫu import phiếu kế hoạch',
        type: 'success',
      });
    } catch {
      dispatchAppToast(dispatch, {
        message: 'Không tải được file mẫu',
        type: 'error',
      });
    } finally {
      setDownloading(false);
    }
  };

  const handleFile = async (file: File | null) => {
    setResult(null);
    setParseError(null);
    setRows([]);
    if (!file) {
      setFileName('');
      return;
    }
    setFileName(file.name);
    try {
      const buf = await file.arrayBuffer();
      const parsed = parsePlanVoucherImportFile(buf);
      setRows(parsed);
      if (parsed.length === 0) {
        setParseError('File không có dòng dữ liệu (sheet KeHoach).');
      }
    } catch (e) {
      setParseError(e instanceof Error ? e.message : 'Không đọc được file Excel');
    }
  };

  const handleImport = async () => {
    if (rows.length === 0) {
      dispatchAppToast(dispatch, { message: 'Chưa có dòng để import', type: 'error' });
      return;
    }
    setImporting(true);
    setResult(null);
    try {
      const res = await fpcService.importPlanVouchers({
        rows,
        expandAfterImport: true,
      });
      setResult(res);
      if (res.errors?.length) {
        dispatchAppToast(dispatch, {
          message: `Import lỗi ${res.errors.length} dòng — kiểm tra chi tiết`,
          type: 'error',
        });
        return;
      }
      dispatchAppToast(dispatch, {
        message: `Import thành công · ${res.vouchersCreated} phiếu mới · ${res.linesUpserted} dòng`,
        type: 'success',
      });
      onImported();
      resetState();
      onClose();
    } catch {
      dispatchAppToast(dispatch, {
        message: 'Lỗi khi import phiếu kế hoạch',
        type: 'error',
      });
    } finally {
      setImporting(false);
    }
  };

  return (
    <Modal
      open={open}
      title="Import phiếu kế hoạch"
      width={640}
      onCancel={handleClose}
      footer={(
        <>
          <Button
            variant="secondary"
            size="md"
            onClick={handleClose}
            disabled={importing}
            data-testid={`${TEST_ID}-cancel`}
          >
            Đóng
          </Button>
          <Button
            variant="primary"
            size="md"
            onClick={() => void handleImport()}
            disabled={importing || rows.length === 0 || !!parseError}
            data-testid={`${TEST_ID}-submit`}
          >
            {importing ? 'Đang import…' : `Import${rows.length ? ` (${rows.length} dòng)` : ''}`}
          </Button>
        </>
      )}
    >
      <div className={styles.body} data-testid={`${TEST_ID}-body`}>
        <p className={styles.hint}>
          Tải file mẫu: sheet <strong>HuongDan</strong> (hướng dẫn chi tiết lịch cố định / định kỳ)
          → điền sheet <strong>KeHoach</strong> (dropdown <strong>MÃ - Tên</strong> cho ĐVCS, mã CP,
          LichRieng, LoaiLich, TanSuat). Xem 6 dòng mẫu sẵn trên KeHoach rồi thay số liệu thật.
        </p>

        <div className={styles.actions}>
          <Button
            variant="secondary"
            size="md"
            onClick={() => void handleDownloadTemplate()}
            disabled={downloading}
            data-testid={`${TEST_ID}-download-template`}
          >
            <i className="fas fa-download" aria-hidden />
            {' '}
            {downloading ? 'Đang tải…' : 'Tải file mẫu'}
          </Button>
          <label className={styles.fileBtn}>
            <input
              ref={fileRef}
              type="file"
              accept=".xlsx,.xls"
              className={styles.fileInput}
              data-testid={`${TEST_ID}-file`}
              onChange={e => void handleFile(e.target.files?.[0] ?? null)}
            />
            <span className={styles.fileLabel}>
              <i className="fas fa-file-excel" aria-hidden />
              {' '}
              Chọn file Excel
            </span>
          </label>
        </div>

        {fileName && (
          <p className={styles.fileName} data-testid={`${TEST_ID}-file-name`}>
            File: {fileName}
            {rows.length > 0 ? ` · ${rows.length} dòng` : ''}
          </p>
        )}

        {parseError && (
          <div className={styles.error} data-testid={`${TEST_ID}-parse-error`}>
            {parseError}
          </div>
        )}

        {rows.length > 0 && !parseError && (
          <div className={styles.preview} data-testid={`${TEST_ID}-preview`}>
            <table className={styles.table}>
              <thead>
                <tr>
                  <th>Dòng</th>
                  <th>ĐVCS</th>
                  <th>Mã CP</th>
                  <th>Kỳ</th>
                  <th>Kế hoạch</th>
                  <th>Phải chi</th>
                  <th>Lịch</th>
                </tr>
              </thead>
              <tbody>
                {rows.slice(0, 8).map(r => (
                  <tr key={`${r.rowIndex}-${r.companyCode}-${r.costCode}`}>
                    <td>{r.rowIndex}</td>
                    <td title={r.companyCode}>{r.companyCode}</td>
                    <td title={r.costCode}>{r.costCode}</td>
                    <td>{r.month}/{r.year}</td>
                    <td className={styles.num}>
                      {new Intl.NumberFormat('vi-VN').format(r.plannedAmount)}
                    </td>
                    <td className={styles.num}>
                      {new Intl.NumberFormat('vi-VN').format(r.mustPay ?? 0)}
                    </td>
                    <td>
                      {r.useCustomSchedule
                        ? (r.loaiLichRaw || r.planScheduleType || r.tanSuatRaw || 'Riêng')
                        : 'Theo phiếu'}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
            {rows.length > 8 && (
              <p className={styles.more}>… và {rows.length - 8} dòng khác</p>
            )}
          </div>
        )}

        {result?.errors && result.errors.length > 0 && (
          <div className={styles.errorList} data-testid={`${TEST_ID}-errors`}>
            <strong>Lỗi validate ({result.errors.length})</strong>
            <ul>
              {result.errors.slice(0, 12).map((e, i) => (
                <li key={`${e.rowIndex}-${e.field}-${i}`}>
                  Dòng {e.rowIndex}
                  {e.field ? ` · ${e.field}` : ''}
                  : {e.message}
                </li>
              ))}
            </ul>
            {result.errors.length > 12 && (
              <p className={styles.more}>… và {result.errors.length - 12} lỗi khác</p>
            )}
          </div>
        )}
      </div>
    </Modal>
  );
};

export default PlanVoucherImportModal;
